company_map = fold acc = {} for c in input.companies {
    return acc + { [c.domain]: c.name }
}

results = for c in input.contacts {
    is_valid_phone = regex.test(c.phone, "^\+1\d{10}$")
    digits = regex.replace(c.phone, "[^0-9]", "")
    digits_len = text.length(digits)
    new_phone = if is_valid_phone {
        null
    } else if digits_len == 10 {
        "+1" + digits
    } else if digits_len == 11 and text.starts_with(digits, "1") {
        "+" + digits
    } else {
        null
    }

    email_parts = text.split(c.email, "@")
    domain = email_parts[1] if list.length(email_parts) >= 2 else ""
    matched_company = company_map[domain] if domain in company_map else null
    needs_company = c.company == "" and matched_company != null

    phone_fixed = if new_phone != null { 1 } else { 0 }
    company_filled = if needs_company { 1 } else { 0 }

    update_args = {}
    update_args = if new_phone != null { update_args + { phone: new_phone } } else { update_args }
    update_args = if needs_company { update_args + { company: matched_company } } else { update_args }

    result = if new_phone != null or needs_company {
        boundary retry 2 {
            return update_contact({ id: c.id } + update_args)
        } catch err {
            return fail("UPDATE_FAILED", c.id + ": " + err.message)
        }
    } else {
        null
    }

    return { phone_fixed, company_filled }
}

total_phones = fold acc = 0 for r in results { return acc + r.phone_fixed }
total_companies = fold acc = 0 for r in results { return acc + r.company_filled }

return submit_result({ answer: { phones_fixed: total_phones, companies_filled: total_companies } })

